"kind": "propose",
"summary": "The api container in revision 2 is throttled at its 300m CPU limit with 296m usage. Increasing the limit to 450m (1.5x current) would alleviate throttling. Earlier revision 1 had similar throttling but lower limits and was healthy.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Current CPU limit of 300m is insufficient for the workload, causing throttling despite higher than revision 1's 200m.",
    "supporting": ["ev-container_cpu", "ev-rollout_history", "ev-revision_health"],
