    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "450m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit of the api container to 450m, reducing throttling and improving readiness probe success rates.",
  "rationale": "The container is throttled at 300m limit with 296m usage. Increasing to 450m (1.5x current) provides buffer without risking memory. Earlier revision 1 was healthy with similar throttling but lower limits, suggesting the current limit may still be insufficient.",
